def topological_sort(graph):
    visited = set()
    order = []
    temp = set()  # for cycle detection

    def visit(node):
        if node in temp:
            raise ValueError('cycle detected')
        if node in visited:
            return
        temp.add(node)
        for dependency in graph.get(node, []):
            visit(dependency)
        temp.remove(node)
        visited.add(node)
        order.append(node)

    for node in graph:
        visit(node)
    return order
```

