def parse_csv_line(line):
    """Parse one CSV line, preserving commas inside quoted fields and decoding doubled quotes."""
    fields = []
    current = []
    in_quotes = False
    i = 0
    while i < len(line):
        c = line[i]
        if c == '"':
            if in_quotes:
                if i + 1 < len(line) and line[i + 1] == '"':
                    current.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                in_quotes = True
                i += 1
        elif c == ',' and not in_quotes:
            fields.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(c)
            i += 1
    fields.append(''.join(current))
    return fields
```

