    return lo
```

```python
def group_anagrams(words):
    groups = {}
    for w in words:
        key = ''.join(sorted(w.lower()))
        groups.setdefault(key, []).append(w)
    return list(groups.values())
```

```python
def is_balanced(s):
    depth = 0
    for c in s:
        if c in '([{':
            depth += 1
        elif c in ')]}':
            depth -= 1
            if depth < 0:
                return False
    return depth == 0
```

